const avatar=(c,large=false)=>`<span class="avatar ${['rose','sage','sand','lavender','blue'].includes(c.color)?c.color:'lavender'} ${large?'large':''}">${esc(initials(c.name))}</span>`;
const C=id=>state.clients.find(c=>c.id===id),G=id=>state.groups.find(g=>g.id===id),T=id=>TESTS.find(t=>t.id===id);
