function commit(update,{renderNow=true}={}){if(recovery){notify('Сначала восстановите базу в настройках. Исходное хранилище не перезаписано.');return false}const next=structuredClone(state);try{update(next);persist(localStorage,next);state=next;storageError='';if(renderNow)render();return true}catch(e){notify('Изменение не сохранено: '+(e.message||'браузер не разрешил запись'));return false}}
