function empty(title,text,button=''){return `<div class="empty">${I('leaf',32)}<h3>${esc(title)}</h3><p>${esc(text)}</p>${button}</div>`}
const person=(c)=>`<div class="person">${avatar(c)}<div><strong>${esc(c.name)}</strong><small>${ageText(ageOf(c.birth))}${ageOf(c.birth)<18?' · подросток':''}</small></div></div>`;
