function render(){if(run){renderRun();return}const pages={clients:'Журнал пациентов',client:'Карточка клиента',calendar:'Календарь',journal:'Журнал мероприятий',tests:'Тестирование',groups:'Группы',group:'Карточка группы',settings:'Настройки'};app.innerHTML=`<div class="layout"><aside class="sidebar"><div class="brand"><span class="brand-mark">п</span><div><div class="brand-name">Практика</div><small>пространство психолога</small></div></div><div><div class="nav-label">Моя практика</div><nav class="nav" aria-label="Основная навигация">${[['clients','users','Журнал пациентов'],['calendar','calendar','Календарь'],['journal','journal','Журнал мероприятий'],['tests','clipboard','Тестирование'],['groups','groups','Группы']].map(([p,i,label])=>`<button type="button" data-action="nav" data-page="${p}" class="${route.page===p||(p==='clients'&&route.page==='client')||(p==='groups'&&route.page==='group')?'active':''}">${I(i)}${label}</button>`).join('')}</nav></div><div class="secondary-nav"><div class="nav-label">Рабочие инструменты</div><nav class="nav"><button type="button" data-action="guide">${I('help')}Как показать демку</button><button type="button" data-action="nav" data-page="settings" class="${route.page==='settings'?'active':''}">${I('settings')}Настройки</button></nav></div><div class="side-bottom"><div class="demo-card"><strong><span class="dot"></span>Демонстрационный кабинет</strong>Все имена и записи вымышлены. Изменения сохраняются в этом браузере.<button type="button" data-action="about">О данных и диагностике</button></div><div class="profile"><span class="avatar">${esc(initials(state.settings.psychologist))}</span><div><strong>${esc(state.settings.psychologist)}</strong><small>Личный кабинет психолога</small></div></div></div></aside><main class="main"><header class="topbar"><span class="breadcrumb">Моя практика <span style="padding:0 10px;color:#b8b2c0">/</span> ${pages[route.page]||'Журнал пациентов'}</span><div class="top-actions"><span class="pill"><span class="dot"></span> Сохранение в браузере</span><span>${fmt(TODAY,{weekday:'long',day:'numeric',month:'long'})}</span>${iconBtn('help','Помощь по демке','guide')}</div></header>${storageError?`<div class="storage-error">${esc(storageError)} ${btn('Настройки','nav',{page:'settings'},'sm')}</div>`:''}<div class="content view-enter" id="view">${({clients:renderClients,client:renderClient,calendar:renderCalendar,journal:renderJournal,tests:renderTests,groups:renderGroups,group:renderGroup,settings:renderSettings}[route.page]||renderClients)()}<footer class="app-footer">Практика · демо рабочего места психолога · данные хранятся только в этом браузере</footer></div></main></div>`}
function renderClients(){let list=state.clients.filter(c=>(clientFilter==='all'||c.status===clientFilter)&&(clientAgeFilter==='all'||(clientAgeFilter==='teen'?ageOf(c.birth)<18:ageOf(c.birth)>=18))&&(`${c.name} ${c.request} ${c.phone}`.toLowerCase().includes(query.toLowerCase())));const monthEvents=state.events.filter(e=>e.status==='completed'&&e.date.startsWith(TODAY.slice(0,7))),todayEvents=state.events.filter(e=>e.status==='planned'&&e.date===TODAY),pending=state.assignments.filter(a=>a.status==='assigned');return heading('Журнал пациентов','Каждая история — в одном месте',btn('Добавить клиента','client-form',{},'primary','plus'))+`<div class="metrics">${[['Клиенты в работе',state.clients.filter(c=>c.status==='active').length,'Текущий состав журнала','users','metric-clients'],['Проведено мероприятий',monthEvents.length,fmt(TODAY,{month:'long',year:'numeric'}),'journal','metric-events'],['Встречи сегодня',todayEvents.length,'Запланированы на '+fmt(TODAY),'calendar','metric-today'],['Ожидают тестирование',pending.length,'Назначенные опросники','clipboard','metric-tests']].map(([label,n,hint,icon,a])=>`<button class="metric" type="button" data-action="${a}"><span class="metric-top">${label}<span class="metric-icon">${I(icon,17)}</span></span><strong>${n}</strong><small>${hint} ${I('arrow',10)}</small></button>`).join('')}</div><div class="journal-layout"><section class="panel"><div class="panel-head"><h2>Мои клиенты <span class="count">${list.length}</span></h2>${btn('Экспорт','export-clients',{},'sm','','')}</div><div class="toolbar">${searchInput(query,'client-search','Поиск по имени, запросу или телефону')}<select id="client-status-filter" aria-label="Статус клиентов">${[['all','Все статусы'],...Object.entries(statusLabel)].map(([v,l])=>`<option value="${v}" ${clientFilter===v?'selected':''}>${l}</option>`).join('')}</select><select id="client-age-filter" aria-label="Возраст клиентов">${[['all','Все возраста'],['adult','Взрослые'],['teen','Подростки']].map(([v,l])=>`<option value="${v}" ${clientAgeFilter===v?'selected':''}>${l}</option>`).join('')}</select></div>${list.length?`<div class="table-wrap"><table><thead><tr><th>Клиент</th><th>Запрос</th><th class="table-secondary">Следующая встреча</th><th>Статус</th><th aria-label="Открыть"></th></tr></thead><tbody>${list.map(c=>{const n=nextEvent(c.id);return `<tr class="clickable" data-action="open-client" data-id="${c.id}"><td><button type="button" class="name-btn" data-action="open-client" data-id="${c.id}">${person(c)}</button></td><td style="max-width:180px;font-size:11px;color:#777581">${esc(c.request)}<div style="font-size:9px;color:#96929e;margin-top:3px">${countCompleted(c.id)} проведённых мероприятий</div></td><td class="table-secondary">${n?`${fmt(n.date)} <small class="muted">· ${esc(n.time)}</small>`:'<span class="muted">Не назначена</span>'}</td><td>${badge(statusLabel[c.status]||'В работе',c.status)}</td><td>${I('arrow',14)}</td></tr>`}).join('')}</tbody></table></div>`:empty('Клиенты не найдены','Измените поиск или фильтры.',btn('Сбросить фильтры','clear-clients',{},'soft'))}<div class="table-footer"><span>Показано ${list.length} из ${state.clients.length} клиентов</span><span>Демонстрационные данные</span></div></section><aside class="panel today-panel"><div class="panel-head"><h2>Сегодня</h2>${btn('Календарь','nav',{page:'calendar'},'sm')}</div><div class="panel-body"><div class="schedule-header"><div><div class="day-number">${TODAY.slice(-2)}</div><div class="schedule-date">${fmt(TODAY,{month:'long',weekday:'long'})}</div></div><span class="metric-icon">${I('calendar',22)}</span></div><div class="schedule-list">${todayEvents.sort((a,b)=>a.time.localeCompare(b.time)).map(e=>`<button type="button" class="appointment" data-action="event-detail" data-id="${e.id}"><time>${esc(e.time)}</time><div><strong>${esc(e.groupId?G(e.groupId)?.name:C(e.clientIds[0])?.name.split(' ').slice(0,2).join(' '))}</strong><p>${esc(e.title)} · ${e.duration} мин</p><span class="appointment-label">${esc(TYPES[e.type])}</span></div></button>`).join('')||'<p class="small-note">На сегодня встреч нет.</p>'}</div><div class="reminder"><strong>Место для спокойной работы</strong>Откройте карточку клиента, чтобы подготовиться к встрече и посмотреть предыдущие записи.</div></div></aside></div>`}
function renderClient(){const c=C(route.id);if(!c)return empty('Карточка не найдена','Вернитесь в журнал пациентов.',btn('Журнал','nav',{page:'clients'}));const events=eventsFor(state,c.id),results=state.results.filter(r=>r.clientId===c.id).sort((a,b)=>b.createdAt.localeCompare(a.createdAt)),assignments=state.assignments.filter(a=>a.clientId===c.id&&a.status==='assigned'),groups=state.groups.filter(g=>g.clientIds.includes(c.id));let body='';if(clientTab==='history')body=`<div class="timeline">${events.length?events.map(e=>`<article class="timeline-item"><div class="event-date">${fullDate(e.date)} · ${esc(e.time)} · ${e.duration} мин</div><div class="event-header"><div><h3>${esc(e.title)}</h3><small class="muted">${esc(TYPES[e.type])}${e.groupId?' · '+esc(G(e.groupId)?.name):''}</small></div>${badge(STATUSES[e.status],e.status)}</div>${e.status==='completed'?`<div class="event-note"><div class="notes-grid">${[['Цель',e.goal],['Краткие выводы',e.conclusions],['Поведение клиента',e.behavior],['Выводы клиента',e.clientInsight],['Дальнейшая работа и прогноз',e.forecast]].filter(([,v])=>v).map(([l,v])=>`<div><strong>${l}</strong><span class="pre">${esc(v)}</span></div>`).join('')}</div></div>`:`<p class="small-note" style="margin-top:9px">${esc(e.goal)}</p>`}<div class="event-actions">${btn('Открыть запись','event-detail',{id:e.id},'sm')}${e.status==='planned'?btn('Провести встречу','event-form',{id:e.id,complete:1},'sm soft'):''}</div></article>`).join(''):empty('История начинается здесь','Добавьте первую консультацию или назначьте диагностику.',btn('Добавить мероприятие','event-form',{client:c.id},'primary','plus'))}</div>`;
 if(clientTab==='tests')body=`<div class="panel-body">${assignments.length?`<h3>Назначено <span class="count">${assignments.length}</span></h3>${assignments.map(a=>`<div class="group-chip section-gap"><div><strong>${esc(T(a.testId)?.title||'Опросник')}</strong><div class="small-note">${fullDate(a.date)} · ожидает прохождения</div></div><div class="actions">${btn('Начать','start-assignment',{id:a.id},'sm primary')}${iconBtn('close','Отменить назначение','cancel-assignment',{id:a.id})}</div></div>`).join('')}<div style="height:25px"></div>`:''}<h3>Результаты <span class="count">${results.length}</span></h3>${results.length?results.map(r=>`<div class="group-chip section-gap"><div><strong>${esc(T(r.testId)?.title||r.title)}</strong><div class="small-note">${fullDate(r.date)} · ${esc(r.result.label)}</div></div><div class="actions">${badge(r.result.score===null?'Профиль':`${r.result.score} / ${r.result.max}`,'planned')}${btn('Разбор','result-detail',{id:r.id},'sm')}</div></div>`).join(''):empty('Пока нет результатов','Выберите опросник. Результат сохранится здесь и в журнале мероприятий.',btn('Выбрать диагностику','choose-test',{client:c.id},'soft','clipboard'))}</div>`;
 if(clientTab==='plan')body=`<div class="panel-body"><h3>План работы</h3><p class="small-note" style="margin:7px 0 20px">Цели и дальнейшие шаги психолога. План можно менять по ходу работы.</p><form id="plan-form" data-client="${c.id}"><label class="field">План следующего этапа<textarea name="plan" rows="7" maxlength="6000">${esc(c.plan)}</textarea></label><label class="field section-gap">Заметка к карточке<textarea name="notes" rows="4" maxlength="6000">${esc(c.notes)}</textarea></label><div class="form-footer">${btn('Собрать черновик из встреч','draft-plan',{client:c.id},'soft','file')}<button class="btn primary" type="submit">Сохранить план</button></div></form></div>`;
 return `<button class="back" data-action="nav" data-page="clients">${I('back',14)}Журнал пациентов</button><section class="panel"><div class="client-hero">${avatar(c,true)}<div class="hero-copy"><div class="eyebrow">Карточка клиента</div><h1>${esc(c.name)}</h1><div class="client-meta"><span>${ageText(ageOf(c.birth))} · ${fmt(c.birth,{day:'numeric',month:'numeric',year:'numeric'})}</span><span>${esc(c.phone)||'Телефон не указан'}</span>${badge(statusLabel[c.status],c.status)}</div><p class="client-request">Запрос: ${esc(c.request)||'Уточняется'}</p></div><div class="actions">${btn('Редактировать','client-form',{id:c.id},'','edit')}${btn('Справка','certificate',{client:c.id},'','file')}</div></div></section><div class="two-col section-gap"><section class="panel"><div class="panel-head"><h2>Работа с клиентом</h2>${btn('Мероприятие','event-form',{client:c.id},'primary sm','plus')}</div><div class="tabs" role="tablist">${[['history','История мероприятий',events.length],['tests','Диагностика',results.length],['plan','План работы','']].map(([v,l,n])=>`<button type="button" role="tab" aria-selected="${clientTab===v}" class="${clientTab===v?'active':''}" data-action="client-tab" data-tab="${v}">${l}${n!==''?' <span class="count">'+n+'</span>':''}</button>`).join('')}</div>${body}</section><aside><section class="panel"><div class="panel-head"><h2>Контекст работы</h2></div><div class="panel-body"><dl class="info-list"><div><dt>Согласие на работу / обработку данных</dt><dd>${c.consent?badge('Отмечено в демке','completed'):badge('Требует уточнения','warning')}</dd></div>${ageOf(c.birth)<18?`<div><dt>Законный представитель</dt><dd>${esc(c.guardian)||'Не указан'}</dd></div>`:''}<div><dt>Проведено мероприятий</dt><dd>${countCompleted(c.id)} · весь период</dd></div><div><dt>Следующая встреча</dt><dd>${nextEvent(c.id)?`${fullDate(nextEvent(c.id).date)}, ${nextEvent(c.id).time}`:'Пока не назначена'}</dd></div><div><dt>Рабочая заметка</dt><dd class="pre">${esc(c.notes)||'Пока нет заметок'}</dd></div></dl><div class="section-gap">${btn('Назначить тест','choose-test',{client:c.id},'soft full-width','clipboard')}</div></div></section><section class="panel section-gap"><div class="panel-head"><h2>Группы клиента</h2>${iconBtn('plus','Добавить в группу','join-group',{client:c.id})}</div><div class="panel-body">${groups.map(g=>`<div class="group-chip" style="margin-bottom:10px"><button class="link-btn" data-action="open-group" data-id="${g.id}">${esc(g.name)}</button>${I('groups',15)}</div>`).join('')||'<p class="small-note">Клиент пока не состоит в группах.</p>'}</div></section></aside></div>`}
function renderTests(){const cats=[...new Set(TESTS.map(t=>t.category))];const filtered=TESTS.filter(t=>(testCategory==='all'||t.category===testCategory)&&(`${t.title} ${t.description}`.toLowerCase().includes(testQuery.toLowerCase())));return heading('Тестирование','Выбирайте методику под запрос и возраст клиента',btn('Назначенные тесты','assignments',{},'','clipboard'))+`<div class="catalog-intro"><span class="intro-icon">${I('leaf',29)}</span><div><h2>Диагностика с понятным разбором</h2><p>${TESTS.length} опросника и шкалы: клинические скрининги и 30 отдельных шкал модели IPIP-NEO. Клиент проходит опросник на этом компьютере; ответы, расчёт и пояснение сохраняются в его карточке.</p></div></div><div class="notice purple">Личностные шкалы IPIP — части одной модели, а не 30 независимых клинических тестов. Русский перевод IPIP в демке не валидирован. Скрининги не устанавливают диагноз. Возрастные ограничения указаны в карточках методик.</div><div class="catalog-toolbar">${searchInput(testQuery,'test-search','Найти опросник или тему')}<div class="chips">${['all',...cats].map(cat=>`<button class="chip ${testCategory===cat?'active':''}" data-action="test-category" data-category="${esc(cat)}">${cat==='all'?'Все '+TESTS.length:esc(cat)}</button>`).join('')}</div></div><div class="test-grid">${filtered.map((t,i)=>`<article class="test-card"><div class="test-card-top"><span class="test-symbol">${I(t.kind==='ipip-full'?'users':t.kind==='ipip'?'leaf':'clipboard',21)}</span>${badge(t.kind==='ipip'?'Шкала IPIP':t.kind==='ipip-full'?'Полный профиль':'Скрининг','')}</div><h3>${esc(t.title)}</h3><p>${esc(t.description)}</p><div class="test-meta"><span>${questionsText(t.questions.length)}</span><span>~ ${t.minutes} мин</span><span>${t.ageMin}+</span></div><div class="actions">${btn('Подробнее','test-detail',{test:t.id},'sm')}${btn('Выбрать','assign-test',{test:t.id},'sm soft','arrow')}</div></article>`).join('')}</div>${!filtered.length?empty('Опросники не найдены','Измените название или категорию.',btn('Все опросники','clear-tests',{},'soft')):''}`}
function renderGroups(){return heading('Группы','Состав, встречи и история групповой работы',btn('Создать группу','group-form',{},'primary','plus'))+`<div class="group-grid">${state.groups.map(g=>`<article class="panel group-card"><div class="group-cover"><div><div class="eyebrow">Групповая работа</div><h2>${esc(g.name)}</h2><p>${esc(g.audience)}</p></div>${I('groups',39)}</div><div class="panel-body"><div class="actions" style="justify-content:space-between"><span class="muted" style="font-size:11px">${g.clientIds.length} из ${g.capacity} участников</span>${badge(g.clientIds.length===g.capacity?'Группа заполнена':'Есть места',g.clientIds.length===g.capacity?'':'active')}</div><div class="avatars">${g.clientIds.map(id=>avatar(C(id))).join('')||'<span class="small-note">Пока нет участников</span>'}</div><p class="group-desc">${esc(g.description)}</p><div class="actions">${btn('Открыть группу','open-group',{id:g.id},'soft','arrow')}${btn('Запланировать встречу','event-form',{group:g.id},'','calendar')}</div></div></article>`).join('')}</div>${!state.groups.length?empty('Создайте первую группу','Объедините клиентов для тренинга или другого группового мероприятия.',btn('Создать группу','group-form',{},'primary')):''}`}
function renderGroup(){const g=G(route.id);if(!g)return empty('Группа не найдена','Откройте список групп.',btn('Группы','nav',{page:'groups'}));const events=state.events.filter(e=>e.groupId===g.id).sort((a,b)=>(b.date+b.time).localeCompare(a.date+a.time));return `<button class="back" data-action="nav" data-page="groups">${I('back',14)}Все группы</button><div class="panel"><div class="group-detail-head"><div class="heading" style="margin:0"><div><div class="eyebrow">Групповая работа · ${g.clientIds.length} / ${g.capacity}</div><h1>${esc(g.name)}</h1><p>${esc(g.audience)} · ${esc(g.description)}</p></div><div class="actions">${btn('Редактировать','group-form',{id:g.id},'','edit')}${btn('Встреча','event-form',{group:g.id},'primary','plus')}</div></div></div></div><div class="two-col section-gap"><div class="panel"><div class="panel-head"><h2>Встречи группы</h2></div><div class="panel-body">${events.map(e=>`<div class="group-chip" style="margin-bottom:14px"><div><strong>${esc(e.title)}</strong><div class="small-note">${fullDate(e.date)} · ${e.time} · ${e.clientIds.length} участников</div>${badge(STATUSES[e.status],e.status)}</div>${btn('Открыть','event-detail',{id:e.id},'sm')}</div>`).join('')||empty('Встреч пока нет','Запланируйте первую встречу группы.')}</div></div><div class="panel"><div class="panel-head"><h2>Участники</h2>${iconBtn('plus','Изменить состав группы','group-form',{id:g.id})}</div><div class="panel-body">${g.clientIds.map(id=>`<button class="name-btn" data-action="open-client" data-id="${id}" style="padding:10px 0;width:100%">${person(C(id))}</button>`).join('')||'<p class="small-note">Состав пуст.</p>'}<p class="small-note section-gap">Состав проведённых встреч сохраняется отдельно и не меняется при редактировании группы.</p></div></div></div>`}
function renderCalendar(){const [y,m]=calendarMonth.split('-').map(Number),first=new Date(y,m-1,1,12),offset=(first.getDay()+6)%7,days=new Date(y,m,0).getDate(),cells=Math.ceil((days+offset)/7)*7;return heading('Календарь','Индивидуальные встречи и группы в общем расписании',btn('Запланировать встречу','event-form',{},'primary','plus'))+`<div class="calendar-tools"><div class="actions">${iconBtn('back','Предыдущий месяц','month',{delta:-1})}<span class="month-label">${fmt(calendarMonth+'-01',{month:'long',year:'numeric'})}</span>${iconBtn('arrow','Следующий месяц','month',{delta:1})}</div>${btn('Сегодня','calendar-today',{},'soft')}</div><div class="calendar-container"><div class="calendar">${['Пн','Вт','Ср','Чт','Пт','Сб','Вс'].map(d=>`<div class="cal-weekday">${d}</div>`).join('')}${Array.from({length:cells},(_,i)=>{const d=localDate(new Date(y,m-1,i-offset+1,12)),ev=state.events.filter(e=>e.date===d).sort((a,b)=>a.time.localeCompare(b.time));return `<div class="cal-day ${d.slice(0,7)!==calendarMonth?'other':''} ${d===TODAY?'today':''}"><button class="cal-number" data-action="day-events" data-date="${d}" aria-label="Встречи ${fullDate(d)}">${+d.slice(-2)}</button>${ev.map(e=>`<button class="cal-event ${e.status}" data-action="event-detail" data-id="${e.id}" title="${esc(e.title)}"><time>${e.time}</time>${esc(eventWho(e).split(' ').slice(0,2).join(' '))}<div>${esc(e.title)}</div></button>`).join('')}</div>`}).join('')}</div></div><div class="legend"><span><i></i>Запланировано</span><span><i class="green"></i>Проведено</span><span>Нажмите на день, чтобы добавить встречу</span></div>`}
function filteredEvents(){return state.events.filter(e=>(journalFilter.status==='all'||e.status===journalFilter.status)&&(journalFilter.type==='all'||e.type===journalFilter.type)&&(!journalFilter.from||e.date>=journalFilter.from)&&(!journalFilter.to||e.date<=journalFilter.to)).sort((a,b)=>(b.date+b.time).localeCompare(a.date+a.time))}
function renderJournal(){const list=filteredEvents();return heading('Журнал мероприятий','Единый журнал консультаций, диагностик и групповых встреч',btn('Добавить запись','event-form',{},'primary','plus'))+`<section class="panel"><div class="journal-filters"><label>Статус<select id="journal-status">${[['all','Все статусы'],...Object.entries(STATUSES)].map(([v,l])=>`<option value="${v}" ${journalFilter.status===v?'selected':''}>${l}</option>`).join('')}</select></label><label>Вид мероприятия<select id="journal-type">${[['all','Все виды'],...Object.entries(TYPES)].map(([v,l])=>`<option value="${v}" ${journalFilter.type===v?'selected':''}>${l}</option>`).join('')}</select></label><label>С даты<input id="journal-from" type="date" value="${journalFilter.from}"></label><label>По дату<input id="journal-to" type="date" value="${journalFilter.to}"></label>${btn('Сбросить','clear-journal',{},'sm')}${btn('Экспорт CSV','export-events',{},'sm','download')}</div>${list.length?`<div class="table-wrap"><table><thead><tr><th>Дата / время</th><th>Клиент / группа</th><th>Мероприятие</th><th>Статус</th><th></th></tr></thead><tbody>${list.map(e=>`<tr class="clickable" data-action="event-detail" data-id="${e.id}"><td>${fmt(e.date)}<div class="small-note">${e.time} · ${e.duration} мин</div></td><td>${esc(eventWho(e))}<div class="small-note">${e.clientIds.length} ${e.clientIds.length===1?'клиент':'участника'}</div></td><td><button class="link-btn" data-action="event-detail" data-id="${e.id}">${esc(e.title)}</button><div class="small-note">${esc(TYPES[e.type])}</div></td><td>${badge(STATUSES[e.status],e.status)}</td><td>${I('arrow',15)}</td></tr>`).join('')}</tbody></table></div>`:empty('Нет записей за выбранный период','Измените фильтры или добавьте мероприятие.')}<div class="table-footer"><span>${list.length} мероприятий · ${list.filter(e=>e.status==='completed').length} проведено</span><span>Групповая встреча учитывается один раз</span></div></section>`}
function renderSettings(){return heading('Настройки','Кабинет, сохранение данных и восстановление демосценария')+`<div class="settings-grid"><section class="panel"><div class="panel-head"><h2>Профиль психолога</h2></div><form class="panel-body" id="settings-form"><div class="form-grid"><label class="field full">ФИО психолога<input name="psychologist" value="${esc(state.settings.psychologist)}" required maxlength="120"></label><label class="field full">Организация / кабинет<input name="organization" value="${esc(state.settings.organization)}" required maxlength="150"></label><label class="field full">Описание практики<input name="specialty" value="${esc(state.settings.specialty)}" maxlength="200"></label></div><div class="form-footer"><button class="btn primary" type="submit">Сохранить</button></div></form></section><section class="panel"><div class="panel-head"><h2>Данные демки</h2></div><div class="panel-body"><p class="small-note">У каждого посетителя своя копия демобазы. Изменения не передаются другим устройствам. Сохраните резервную копию, чтобы перенести демонстрационный сценарий.</p><div class="actions section-gap">${btn('Скачать копию JSON','backup',{},'','download')}${btn('Восстановить из файла','import',{},'','file')}</div><input id="import-file" class="hidden" type="file" accept="application/json,.json"><div class="notice section-gap">Публичная демонстрация без регистрации. Используйте вымышленные данные. Для реальной практики понадобятся отдельная защищённая база и управление доступом.</div>${recovery?`<div class="notice danger section-gap">${esc(storageError)}</div><div class="actions section-gap">${btn('Скачать исходное хранилище','raw-backup',{},'','download')}</div>`:''}<div class="section-gap">${btn('Восстановить демоданные','reset',{},'danger')}</div><p class="small-note section-gap">Сброс заменит только данные Практики в этом браузере. Перед ним можно скачать резервную копию.</p></div></section><section class="panel"><div class="panel-head"><h2>Методики и интерпретации</h2></div><div class="panel-body"><p class="small-note">В каталоге ${TESTS.length} инструментов. Источники, возраст, формулы и ограничения доступны в описании каждого опросника и в сохранённом разборе. Русский перевод IPIP сделан для демонстрации; возрастные нормы не применяются.</p><div class="actions section-gap">${btn('Открыть каталог','nav',{page:'tests'},'soft')}${btn('О диагностике','about')}</div></div></section><section class="panel"><div class="panel-head"><h2>Сценарий демонстрации</h2></div><div class="panel-body"><p class="small-note">Создайте клиента, запишите консультацию, назначьте тест и добавьте его в группу. Все действия связаны с карточкой клиента, журналом и календарём.</p><div class="section-gap">${btn('Показать шаги','guide',{},'soft','help')}</div></div></section></div>`}
function openModal(title,subtitle,body,wide=false){lastFocus=document.activeElement;modal.className=wide?'wide':'';modal.innerHTML=`<header class="modal-head"><div><h2 id="modal-title">${esc(title)}</h2><p>${esc(subtitle)}</p></div><button type="button" class="modal-close" aria-label="Закрыть" data-action="close">${I('close',17)}</button></header><div class="modal-body">${body}</div>`;if(!modal.open)modal.showModal();modal.scrollTop=0}
function closeModal(){if(modal.open)modal.close();if(lastFocus?.isConnected)lastFocus.focus()}
modal.addEventListener('click',e=>{if(e.target===modal){const r=modal.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal()}});
function field(label,name,value='',options={}){const {type='text',required=false,full=false,max=6000,rows=3,helper='',extra=''}=options;return `<label class="field ${full?'full':''}"><span>${label}${required?' <span class="required">*</span>':''}</span>${type==='textarea'?`<textarea name="${name}" rows="${rows}" maxlength="${max}" ${required?'required':''} ${extra}>${esc(value)}</textarea>`:`<input name="${name}" type="${type}" value="${esc(value)}" maxlength="${max}" ${required?'required':''} ${extra}>`}${helper?`<span class="helper">${helper}</span>`:''}</label>`}
function selectField(label,name,choices,value,full=false){return `<label class="field ${full?'full':''}">${label}<select name="${name}">${choices.map(([v,l])=>`<option value="${esc(v)}" ${v===value?'selected':''}>${esc(l)}</option>`).join('')}</select></label>`}
function formEnd(label='Сохранить'){return `<div class="form-footer">${btn('Отмена','close')}<button class="btn primary" type="submit">${label}</button></div>`}
function clientForm(id){const c=C(id)||{name:'',birth:'',phone:'',request:'',status:'active',guardian:'',notes:'',plan:'',consent:false};openModal(id?'Редактировать клиента':'Новый клиент','Данные используются только в этой демонстрации.',`<form id="client-form" data-id="${id||''}"><div class="form-error" role="alert"></div><div class="form-grid">${field('ФИО','name',c.name,{required:true,full:true,max:150})}${field('Дата рождения','birth',c.birth,{type:'date',required:true,extra:`max="${TODAY}" min="1900-01-01"`})}${field('Телефон (демонстрационный)','phone',c.phone,{type:'tel',max:50})}${field('Запрос клиента','request',c.request,{required:true,full:true,max:300})}${selectField('Статус работы','status',Object.entries(statusLabel),c.status)}${field('Законный представитель (для несовершеннолетних)','guardian',c.guardian,{max:200})}${field('Рабочая заметка','notes',c.notes,{type:'textarea',full:true})}<label class="checkbox full"><input name="consent" type="checkbox" ${c.consent?'checked':''}>Согласие на работу и обработку данных отмечено психологом (демонстрационная отметка)</label></div>${formEnd(id?'Сохранить изменения':'Создать карточку')}</form>`)}
function eventForm(data={}){const existing=state.events.find(e=>e.id===data.id),group=G(data.group||existing?.groupId),clientId=data.client||existing?.clientIds[0]||state.clients[0]?.id,e=existing||{date:data.date||TODAY,time:'11:00',duration:group?90:50,type:group?'training':'consultation',title:'',status:'planned',goal:'',conclusions:'',behavior:'',clientInsight:'',forecast:'',clientIds:group?[...group.clientIds]:[clientId]};if(!state.clients.length){notify('Сначала добавьте клиента.');return}const completed=data.complete?'completed':e.status;openModal(existing?'Запись мероприятия':'Новое мероприятие',group?`Группа «${group.name}» · отметьте фактических участников`:'Встреча появится в карточке клиента и календаре.',`<form id="event-form" data-id="${existing?.id||''}" data-group="${group?.id||''}"><div class="form-error" role="alert"></div><div class="form-grid">${group?`<div class="field full">Участники встречи<div class="check-list">${[...new Set([...group.clientIds,...(existing?.clientIds||[])])].map(id=>`<label class="checkbox"><input type="checkbox" name="clientIds" value="${id}" ${e.clientIds.includes(id)?'checked':''}>${esc(C(id)?.name)}</label>`).join('')}</div><span class="helper">История клиента включает только мероприятия, где он выбран участником.</span></div>`:selectField('Клиент','clientId',state.clients.map(c=>[c.id,c.name]),clientId,true)}${field('Название мероприятия','title',e.title,{required:true,full:true,max:200})}${selectField('Вид мероприятия','type',Object.entries(TYPES).filter(([k])=>group?['training','group'].includes(k):['consultation','diagnostic'].includes(k)),e.type)}${selectField('Статус','status',Object.entries(STATUSES),completed)}${field('Дата','date',e.date,{type:'date',required:true})}${field('Время','time',e.time,{type:'time',required:true})}${field('Длительность, минут','duration',e.duration,{type:'number',required:true,extra:'min="1" max="240" step="1"'})}<div></div>${field('Цели консультации / мероприятия','goal',e.goal,{type:'textarea',required:true,full:true})}${field('Краткие выводы психолога','conclusions',e.conclusions,{type:'textarea',full:true})}${field('Как вёл себя клиент / участники','behavior',e.behavior,{type:'textarea'})}${field('К каким выводам пришёл клиент','clientInsight',e.clientInsight,{type:'textarea'})}${field('Дальнейшая работа и прогноз психолога','forecast',e.forecast,{type:'textarea',full:true,helper:'Формулируется специалистом; программа не прогнозирует состояние клиента.'})}</div>${group?'<div class="notice purple section-gap">Общая заметка будет видна в истории всех отмеченных участников. Индивидуальные наблюдения можно добавить отдельной консультацией.</div>':''}${formEnd(completed==='completed'?'Сохранить проведённую встречу':'Сохранить мероприятие')}</form>`,true)}
function eventDetail(id){const e=state.events.find(x=>x.id===id);if(!e)return;openModal(e.title,`${fullDate(e.date)} · ${e.time} · ${e.duration} минут`,`${badge(STATUSES[e.status],e.status)} <span class="small-note">${esc(TYPES[e.type])}</span><div class="detail-grid section-gap"><div class="full"><dt>Клиент / участники</dt><dd>${e.clientIds.map(id=>`<button type="button" class="link-btn" data-action="open-client" data-id="${id}">${esc(C(id)?.name)}</button>`).join('<br>')}</dd></div>${[['Цели',e.goal],['Краткие выводы',e.conclusions],['Поведение',e.behavior],['Выводы клиента',e.clientInsight],['Дальнейшая работа / прогноз',e.forecast]].map(([title,v])=>`<div class="full"><dt>${title}</dt><dd>${esc(v)||'<span class="muted">Не заполнено</span>'}</dd></div>`).join('')}</div>${e.resultId?`<div class="section-gap">${btn('Открыть результат диагностики','result-detail',{id:e.resultId},'soft','clipboard')}</div>`:''}<div class="form-footer">${e.status==='planned'?btn('Отменить встречу','cancel-event',{id:e.id},'danger'):''}${e.status==='cancelled'?btn('Вернуть в план','restore-event',{id:e.id}):''}${btn('Редактировать','event-form',{id:e.id},'','edit')}${e.status==='planned'?btn('Провести встречу','event-form',{id:e.id,complete:1},'primary','check'):''}</div>`)}
function groupForm(id){const g=G(id)||{name:'',audience:'Взрослые · 18+',description:'',capacity:8,clientIds:[]};openModal(id?'Редактировать группу':'Новая группа','Состав группы и записи проведённых встреч хранятся отдельно.',`<form id="group-form" data-id="${id||''}"><div class="form-error" role="alert"></div><div class="form-grid">${field('Название группы','name',g.name,{required:true,full:true,max:150})}${selectField('Аудитория','audience',[['Взрослые · 18+','Взрослые · 18+'],['Подростки 14–17 лет','Подростки 14–17 лет'],['Смешанная группа · 14+','Смешанная группа · 14+']],g.audience)}${field('Максимум участников','capacity',g.capacity,{type:'number',required:true,extra:'min="1" max="30"'})}${field('Цель и описание группы','description',g.description,{type:'textarea',required:true,full:true})}<div class="field full">Участники<div class="check-list">${state.clients.map(c=>`<label class="checkbox"><input type="checkbox" name="clientIds" value="${c.id}" ${g.clientIds.includes(c.id)?'checked':''}>${esc(c.name)} <small class="muted">${ageText(ageOf(c.birth))}</small></label>`).join('')}</div><span class="helper">Возраст участников должен соответствовать аудитории группы. Для смешанной группы психолог отдельно оценивает уместность состава.</span></div></div>${formEnd(id?'Сохранить состав':'Создать группу')}</form>`)}
function joinGroup(client){const c=C(client);openModal('Добавить в группу',c.name,`<form id="join-group" data-client="${client}"><div class="form-error" role="alert"></div>${selectField('Группа','groupId',state.groups.filter(g=>!g.clientIds.includes(client)).map(g=>[g.id,`${g.name} · ${g.clientIds.length}/${g.capacity}`]),'',true)}<p class="small-note section-gap">Добавление в состав не меняет проведённые встречи и не записывает клиента автоматически на уже запланированные встречи. Участников каждой встречи отмечает психолог.</p>${formEnd('Добавить участника')}</form>`)}
function testDetail(id){const t=T(id);if(!t)return;openModal(t.title,`${questionsText(t.questions.length)} · около ${t.minutes} мин · ${t.ageMin}+`,`<div class="test-description">${esc(t.description)}</div><dl class="detail-grid"><div class="full"><dt>Инструкция участнику</dt><dd>${esc(t.instruction)}</dd></div><div class="full"><dt>Формат</dt><dd>${t.kind==='ipip'?'Четыре утверждения об одной личностной черте. Шкала входит в модель IPIP-NEO-120.':t.kind==='ipip-full'?'Профиль по 30 личностным шкалам. Единого балла личности нет.':'Короткий опросник для скрининга симптомов за последние две недели.'}</dd></div><div class="full"><dt>Источник</dt><dd><a href="${esc(t.source.url)}" target="_blank" rel="noopener noreferrer">${esc(t.source.label)}</a></dd></div></dl><div class="notice section-gap">${esc(t.limitation)}</div><div class="form-footer">${btn('Закрыть','close')}${btn('Выбрать клиента','assign-test',{test:id},'primary','arrow')}</div>`)}
function chooseTest(client){const c=C(client),age=ageOf(c.birth);openModal('Назначить диагностику',c.name,`<form id="choose-test" data-client="${client}"><div class="form-error" role="alert"></div>${selectField('Опросник или шкала','testId',TESTS.filter(t=>age>=t.ageMin).map(t=>[t.id,`${t.title} · ${questionsText(t.questions.length)}`]),'',true)}<div class="notice purple section-gap">${age<18?'Для подростка доступны демонстрационные личностные шкалы 14+. Взрослые клинические пороги не применяются. Психолог оценивает применимость опросника.':'Перед прохождением психолог проверяет описание, ограничения и согласие клиента.'}</div><div class="form-footer">${btn('Отмена','close')}<button type="submit" class="btn soft" name="mode" value="assign">Назначить на потом</button><button type="submit" class="btn primary" name="mode" value="start">Начать сейчас</button></div></form>`)}
function assignTest(test,client=''){const t=T(test);if(!t)return;openModal('Кому назначить опросник?',t.title,`<form id="assign-test" data-test="${test}"><div class="form-error" role="alert"></div>${selectField('Клиент','clientId',state.clients.filter(c=>ageOf(c.birth)>=t.ageMin&&c.status!=='finished').map(c=>[c.id,`${c.name} · ${ageText(ageOf(c.birth))}${!c.consent?' · согласие не отмечено':''}`]),client,true)}<div class="notice section-gap">${esc(t.limitation)}</div><p class="small-note section-gap">В режиме прохождения видны только вопросы текущего опросника. Это удобство демонстрации, не механизм защиты доступа.</p><div class="form-footer">${btn('Подробнее','test-detail',{test})}<button type="submit" class="btn soft" name="mode" value="assign">Назначить на потом</button><button type="submit" class="btn primary" name="mode" value="start">Начать сейчас</button></div></form>`)}
function assignmentsModal(){const list=state.assignments.filter(a=>a.status==='assigned');openModal('Назначенное тестирование',`${list.length} опросников ожидают прохождения`,list.length?list.map(a=>`<div class="group-chip" style="margin-bottom:12px"><div><strong>${esc(C(a.clientId)?.name)}</strong><div class="small-note">${esc(T(a.testId)?.title)}</div></div><div class="actions">${btn('Начать','start-assignment',{id:a.id},'sm primary')}${iconBtn('close','Отменить назначение','cancel-assignment',{id:a.id})}</div></div>`).join(''):empty('Всё пройдено','Выберите опросник в каталоге и назначьте клиенту.'))}
function beginTest(testId,clientId,assignmentId=null){const t=T(testId),c=C(clientId);if(!t||!c)return;if(ageOf(c.birth)<t.ageMin){notify('Опросник недоступен для этого возраста.');return}if(!c.consent){notify('Отметьте согласие в карточке клиента перед тестированием.');return}const draft=state.drafts[`${clientId}:${testId}`];run={testId,clientId,assignmentId,index:draft?.index||0,answers:draft?.answers||Array(t.questions.length).fill(null),completed:false};closeModal();render();window.scrollTo(0,0)}
function renderRun(){const t=T(run.testId),c=C(run.clientId),answered=run.answers.filter(x=>x!==null).length;app.innerHTML=`<div class="participant"><header class="participant-top"><div class="brand"><span class="brand-mark">п</span><div><div class="brand-name">Практика</div><small>режим прохождения</small></div></div>${btn('Вернуться к психологу','exit-test',{},'','back')}</header><div class="participant-wrap">${run.completed?`<div class="question-card participant-complete"><div class="complete-icon">${I('check',31)}</div><div class="eyebrow">Опросник завершён</div><h1>Спасибо за ваши ответы</h1><p>Ответы сохранены. Психолог сможет обсудить с вами результат и его значение в контексте вашей ситуации.</p>${run.savedResult?.result.alert?`<div class="notice danger" style="text-align:left;margin-bottom:20px">Пожалуйста, сообщите психологу о том, что сейчас вас беспокоит. Важно обсудить этот ответ лично.</div>`:''}${btn('Открыть разбор для психолога','run-result',{},'primary','clipboard')}</div>`:`<div class="participant-kicker"><span>Личный опросник · ${esc(c.name.split(' ')[1]||'Клиент')}</span><span>${answered} / ${t.questions.length} ответов</span></div><h1>${esc(t.title)}</h1><p class="instruction">${esc(t.instruction)}</p><div class="progress" aria-label="Прогресс опросника"><i style="width:${answered/t.questions.length*100}%"></i></div><div class="question-card"><div class="question-number">ВОПРОС ${run.index+1} ИЗ ${t.questions.length}</div><h2>${esc(t.questions[run.index].text)}</h2><div class="answers" role="radiogroup" aria-label="Ответ на вопрос">${t.options.map(o=>`<label class="answer ${run.answers[run.index]===o.value?'selected':''}"><input type="radio" name="answer" value="${o.value}" ${run.answers[run.index]===o.value?'checked':''}><span>${esc(o.label)}</span></label>`).join('')}</div></div><div class="question-nav"><button type="button" class="btn" data-action="prev-question" ${run.index===0?'disabled':''}>${I('back',15)}Назад</button><button type="button" class="btn primary" data-action="${run.index===t.questions.length-1?'finish-test':'next-question'}" ${run.answers[run.index]===null?'disabled':''}>${run.index===t.questions.length-1?'Завершить':'Далее'}${I('arrow',15)}</button></div><div class="participant-footer">Можно вернуться и изменить ответ. Прогресс сохраняется в этом браузере.</div>`}</div></div>`}
function finishTest(){try{const t=T(run.testId),c=C(run.clientId),result=scoreTest(t,run.answers,ageOf(c.birth)),record={id:uid(),clientId:c.id,testId:t.id,title:t.title,answers:[...run.answers],result,date:TODAY,createdAt:new Date().toISOString(),ageAtTest:ageOf(c.birth),birthAtTest:c.birth,source:t.source,limitation:t.limitation};const eventId=uid();const ok=commit(s=>{s.results.push(record);s.events.push({id:eventId,clientIds:[c.id],date:TODAY,time:new Intl.DateTimeFormat('sv-SE',{timeZone:'Europe/Moscow',hour:'2-digit',minute:'2-digit'}).format(new Date()),duration:t.minutes,type:'diagnostic',title:t.title,status:'completed',goal:'Прохождение опросника и обсуждение результата с психологом.',conclusions:`${result.label}. ${result.score===null?'Профиль из 30 шкал':`Баллы: ${result.score} / ${result.max}`}. ${result.summary}`,behavior:'',clientInsight:'',forecast:'Обсудить результат в контексте запроса клиента.',resultId:record.id});if(run.assignmentId){const a=s.assignments.find(a=>a.id===run.assignmentId);if(a)a.status='completed'}else{s.assignments.filter(a=>a.clientId===c.id&&a.testId===t.id&&a.status==='assigned').forEach(a=>a.status='completed')}delete s.drafts[`${c.id}:${t.id}`]}, {renderNow:false});if(ok){run.completed=true;run.savedResult=record;render()}}catch(e){notify(e.message)}}
function resultBody(r){const t=T(r.testId),rs=r.result;return `${rs.alert?`<div class="notice danger">${esc(rs.alert)}</div>`:''}<div class="result-score"><div class="result-number">${rs.score===null?'30':rs.score}<span>${rs.score===null?' шкал':' / '+rs.max}</span></div><div style="flex:1"><h3>${esc(rs.label)}</h3><p>${esc(rs.summary)}</p>${rs.percent!==null&&rs.percent!==undefined?`<div class="progress"><i style="width:${rs.percent}%"></i></div><div class="small-note" style="margin-top:6px">Положение на возможной шкале · не процентиль и не вероятность</div>`:''}</div></div>${rs.facets?`<div class="facets">${rs.facets.map(f=>`<div class="facet"><strong>${esc(f.title)}</strong><small>${f.score} / ${f.max}</small><div class="progress"><i style="width:${f.percent}%"></i></div></div>`).join('')}</div>`:''}${(rs.details||[]).map(d=>`<section class="result-detail"><h3>${esc(d.title)}</h3><p>${esc(d.text)}</p></section>`).join('')}<div class="result-formula">Расчёт: ${esc(rs.formula)}</div><div class="notice section-gap">${esc(r.limitation||t?.limitation)}</div><p class="small-note section-gap">Источник: <a href="${esc((r.source||t?.source)?.url)}" target="_blank" rel="noopener noreferrer">${esc((r.source||t?.source)?.label)}</a> · возраст при прохождении: ${ageText(r.ageAtTest)}</p><details class="section-gap no-print"><summary style="cursor:pointer;font-size:12px;font-weight:600">Ответы и ключ расчёта</summary><div class="table-wrap"><table class="answer-table"><thead><tr><th>Утверждение</th><th>Ответ</th><th>Учтено</th></tr></thead><tbody>${r.answers.map((v,i)=>`<tr><td>${esc(t?.questions[i]?.text)}</td><td>${esc(t?.options.find(o=>o.value===v)?.label)} (${v})</td><td>${t?.questions[i]?.reverse?6-v:v}${t?.questions[i]?.reverse?' · обратный пункт':''}</td></tr>`).join('')}</tbody></table></div></details>`}
function resultDetail(id){const r=state.results.find(r=>r.id===id);if(!r)return;openModal(r.title||T(r.testId)?.title,`${C(r.clientId)?.name} · ${fullDate(r.date)}`,`<div id="result-document">${resultBody(r)}</div><div class="form-footer no-print">${btn('В карточку клиента','result-client',{client:r.clientId})}${btn('Скачать разбор','download-result',{id},'','download')}${btn('Печать / PDF','print-result',{},'primary','print')}</div>`,true)}
function certificate(client){certClient=client;const c=C(client);openModal('Справка о проведённых мероприятиях',c.name,`<div class="report-settings no-print"><label class="field">С даты<input type="date" id="cert-from"></label><label class="field">По дату<input type="date" id="cert-to" value="${TODAY}"></label><label class="checkbox" style="padding-top:23px"><input type="checkbox" id="cert-notes">Включить рабочие выводы</label></div><div id="certificate-preview"></div><div class="form-footer no-print">${btn('Закрыть','close')}${btn('Скачать справку','download-certificate',{},'','download')}${btn('Печать / PDF','print-certificate',{},'primary','print')}</div>`,true);updateCertificate()}
function certificateHtml(c,from,to,notes){const events=eventsFor(state,c.id).filter(e=>e.status==='completed'&&(!from||e.date>=from)&&(!to||e.date<=to)).sort((a,b)=>(a.date+a.time).localeCompare(b.date+b.time));return `<article class="certificate"><div class="doc-mark">${esc(state.settings.organization)} · Практика</div><h2>СПРАВКА</h2><p class="doc-subtitle">о проведённых психологических мероприятиях</p><p>Клиент: <strong>${esc(c.name)}</strong><br>Дата рождения: ${fullDate(c.birth)}<br>Период: ${from?fullDate(from):'с начала работы'} — ${to?fullDate(to):'весь период'}.</p><p style="margin-top:15px">В журнале зарегистрировано проведённых мероприятий: <strong>${events.length}</strong>.</p>${events.length?`<table><thead><tr><th>Дата</th><th>Вид / мероприятие</th><th>Длительность</th></tr></thead><tbody>${events.map(e=>`<tr><td>${fmt(e.date,{day:'2-digit',month:'2-digit',year:'numeric'})}</td><td>${esc(TYPES[e.type])}<br>${esc(e.title)}${notes?`<p style="margin-top:8px">${esc(e.conclusions)||'Выводы не внесены'}</p>`:''}</td><td>${e.duration} мин</td></tr>`).join('')}</tbody></table>`:'<p style="margin:20px 0">В выбранном периоде проведённые мероприятия отсутствуют.</p>'}<p class="small-note">Справка подтверждает только наличие записей в демонстрационном журнале. Запланированные и отменённые мероприятия не включаются.</p><div class="signature"><span>Психолог: ${esc(state.settings.psychologist)}</span><span>Дата: ${fullDate(TODAY)}</span></div><div class="document-banner">Демонстрационный документ · вымышленные данные · не медицинское заключение</div></article>`}
function updateCertificate(){const from=document.querySelector('#cert-from')?.value,to=document.querySelector('#cert-to')?.value,notes=document.querySelector('#cert-notes')?.checked;if(from&&to&&from>to){document.querySelector('#certificate-preview').innerHTML='<div class="notice danger">Начальная дата должна быть раньше конечной.</div>';return}document.querySelector('#certificate-preview').innerHTML=certificateHtml(C(certClient),from,to,notes)}
function download(name,content,type='text/plain;charset=utf-8'){const blob=new Blob([content],{type}),u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1500);notify('Файл подготовлен для скачивания.')}
function standaloneDocument(title,body){return `<!doctype html><html lang="ru"><head><meta charset="utf-8"><title>${esc(title)}</title><style>body{max-width:850px;margin:45px auto;padding:0 24px;font:14px/1.8 system-ui;color:#302d39}table{width:100%;border-collapse:collapse;margin:22px 0}td,th{border-bottom:1px solid #ddd;padding:12px;text-align:left}.doc-mark,.small-note{color:#777;font-size:12px}h2{text-align:center}.doc-subtitle{text-align:center}.signature{display:flex;justify-content:space-between;margin-top:30px}.document-banner,.notice{border:1px solid #ccc;padding:15px;margin-top:20px;font-size:12px}.result-detail{margin:25px 0}.result-number{font-size:32px}.facets{display:grid;grid-template-columns:1fr 1fr;gap:10px}.facet small{margin-left:15px}.result-formula{margin-top:20px;white-space:pre-wrap}@media print{body{margin:0}@page{size:A4;margin:18mm}}</style></head><body>${body}</body></html>`}
function csv(rows){return '\ufeff'+rows.map(row=>row.map(v=>{let s=String(v??'');if(/^[=+\-@\t\r]/.test(s))s="'"+s;return '"'+s.replace(/"/g,'""')+'"'}).join(';')).join('\r\n')}
function exportClients(){const list=state.clients.filter(c=>(clientFilter==='all'||c.status===clientFilter)&&(clientAgeFilter==='all'||(clientAgeFilter==='teen'?ageOf(c.birth)<18:ageOf(c.birth)>=18))&&`${c.name} ${c.request} ${c.phone}`.toLowerCase().includes(query.toLowerCase()));download('Практика-клиенты.csv',csv([['ФИО','Дата рождения','Телефон','Запрос','Статус','Проведено'],...list.map(c=>[c.name,c.birth,c.phone,c.request,statusLabel[c.status],countCompleted(c.id)])]),'text/csv;charset=utf-8')}
function exportEvents(){download('Практика-журнал.csv',csv([['Дата','Время','Клиент / группа','Участники','Вид','Название','Статус','Цель','Выводы','Поведение','Выводы клиента','Прогноз'],...filteredEvents().map(e=>[e.date,e.time,eventWho(e),e.clientIds.map(id=>C(id).name).join(', '),TYPES[e.type],e.title,STATUSES[e.status],e.goal,e.conclusions,e.behavior,e.clientInsight,e.forecast])]),'text/csv;charset=utf-8')}
function about(){openModal('О демке и диагностике','Рабочий сценарий с вымышленными данными.',`<div class="notice purple">Это открытая демонстрация. Не вносите реальные персональные данные клиентов. Общей базы, авторизации и обмена между устройствами здесь нет.</div><section class="result-detail"><h3>Что работает</h3><p>Карточки клиентов, записи консультаций, календарь, состав групп, назначение и прохождение опросников, расчёт результатов, справки и экспорт. Изменения сохраняются локально.</p></section><section class="result-detail"><h3>Как устроен каталог</h3><p>${TESTS.length} опросника и шкалы. В него входят 30 четырёхпунктных шкал единой модели IPIP-NEO, общий профиль и клинические скрининги. Подбор методики и интерпретация остаются за психологом.</p></section><section class="result-detail"><h3>Границы интерпретации</h3><p>Русский перевод IPIP подготовлен для демки и не прошёл отдельную валидацию. Балл описывает ответы, а не диагноз, процентиль или вероятность. Клинические скрининги в демке доступны с 18 лет. Для подростков с 14 лет доступны короткие шкалы IPIP по решению специалиста.</p></section><section class="result-detail"><h3>Черновик плана</h3><p>Собирается из уже внесённых психологом записей по шаблону. Запросов к ИИ нет, новые выводы о человеке не придумываются.</p></section><div class="form-footer">${btn('Понятно','close',{},'primary')}</div>`)}
function guide(){openModal('Покажите полный путь клиента','Всё связано с карточкой, календарём и журналом.',`${[['Откройте клиента','Журнал пациентов → Морозова Анна. Посмотрите две предыдущие консультации.'],['Запишите консультацию','Мероприятие → заполните цель, поведение, выводы и дальнейший план → статус «Проведено».'],['Проведите опросник','Диагностика → Назначить тест → выбрать шкалу → начать. В режиме клиента видны только вопросы.'],['Посмотрите результат','После завершения откройте разбор для психолога: баллы, пояснения, ответы и формула.'],['Добавьте в группу','В карточке клиента нажмите плюс у групп. В группе запланируйте встречу и отметьте участников.'],['Сформируйте справку','Справка → выберите период → скачать или печать / PDF. Только проведённые мероприятия.'],['Проверьте сохранение','Обновите страницу: записи останутся. Настройки → резервная копия или восстановление демоданных.']].map(([title,text],i)=>`<div class="guide-step"><span class="step-number">${i+1}</span><div><h3>${title}</h3><p>${text}</p></div></div>`).join('')}<div class="form-footer">${btn('Начать показ','close',{},'primary')}</div>`)}
function formError(form,msg){form.querySelector('.form-error').textContent=msg}
function validateGroup(g){if(g.clientIds.length>g.capacity)return 'В группе больше участников, чем разрешено мест.';if(!g.name.trim()||!g.description.trim())return 'Заполните название и цель группы.';const unsuitable=g.clientIds.find(id=>{const a=ageOf(C(id).birth);return g.audience.startsWith('Взрослые')?a<18:g.audience.startsWith('Подростки')?(a<14||a>17):a<14});if(unsuitable)return `Возраст клиента ${C(unsuitable).name} не соответствует аудитории группы.`;return ''}
document.addEventListener('submit',event=>{const form=event.target;if(!(form instanceof HTMLFormElement))return;event.preventDefault();const data=new FormData(form),v=name=>String(data.get(name)||'').trim();if(form.id==='client-form'){if(!v('name')||!v('request')){formError(form,'Заполните ФИО и запрос.');return}if(v('birth')>TODAY||ageOf(v('birth'))>125){formError(form,'Проверьте дату рождения.');return}if(ageOf(v('birth'))<18&&!v('guardian')){formError(form,'Для несовершеннолетнего укажите законного представителя.');return}const id=form.dataset.id||uid(),c={id,name:v('name'),birth:v('birth'),phone:v('phone'),request:v('request'),status:v('status'),guardian:v('guardian'),notes:v('notes'),consent:data.has('consent')};if(commit(s=>{const old=s.clients.find(x=>x.id===id);if(old)Object.assign(old,c);else s.clients.push({...c,plan:'',color:['rose','sage','sand','lavender','blue'][s.clients.length%5]})})){go('client',id);notify('Карточка клиента сохранена.')}return}
 if(form.id==='event-form'){const id=form.dataset.id||uid(),old=state.events.find(e=>e.id===id),groupId=form.dataset.group||undefined,clientIds=groupId?data.getAll('clientIds'):[v('clientId')],e={...old,id,clientIds,date:v('date'),time:v('time'),duration:Number(v('duration')),type:v('type'),title:v('title'),status:v('status'),goal:v('goal'),conclusions:v('conclusions'),behavior:v('behavior'),clientInsight:v('clientInsight'),forecast:v('forecast'),...(groupId?{groupId}:{})};if(!e.title||!e.goal){formError(form,'Заполните название и цель мероприятия.');return}if(!clientIds.length){formError(form,'Выберите хотя бы одного участника.');return}if(e.status==='completed'&&e.date>TODAY){formError(form,'Проведённое мероприятие не может быть датировано будущим.');return}if(e.status==='completed'&&!e.conclusions){formError(form,'Для проведённой встречи внесите краткие выводы.');return}const cf=conflictFor(state,e);if(cf){formError(form,`В это время уже есть встреча «${cf.title}» (${cf.time}, ${cf.duration} мин). Выберите другое время.`);return}if(commit(s=>{const ix=s.events.findIndex(x=>x.id===id);if(ix>=0)s.events[ix]=e;else s.events.push(e)})){closeModal();notify('Мероприятие сохранено в журнале и карточке.')}return}
 if(form.id==='group-form'){const id=form.dataset.id||uid(),g={id,name:v('name'),audience:v('audience'),description:v('description'),capacity:Number(v('capacity')),clientIds:data.getAll('clientIds'),color:'sage'},error=validateGroup(g);if(error){formError(form,error);return}if(commit(s=>{const i=s.groups.findIndex(x=>x.id===id);if(i>=0)s.groups[i]=g;else s.groups.push(g)})){go('group',id);notify('Группа сохранена.')}return}
 if(form.id==='join-group'){const g=G(v('groupId'));if(!g){formError(form,'Нет доступной группы. Создайте группу в разделе «Группы».');return}const error=validateGroup({...g,clientIds:[...g.clientIds,form.dataset.client]});if(error){formError(form,error);return}if(commit(s=>s.groups.find(x=>x.id===g.id).clientIds.push(form.dataset.client))){closeModal();notify('Клиент добавлен в группу.')}return}
 if(form.id==='plan-form'){if(commit(s=>Object.assign(s.clients.find(x=>x.id===form.dataset.client),{plan:v('plan'),notes:v('notes')})))notify('План работы сохранён.');return}
 if(form.id==='settings-form'){if(!v('psychologist')||!v('organization'))return;if(commit(s=>s.settings={psychologist:v('psychologist'),organization:v('organization'),specialty:v('specialty')}))notify('Настройки кабинета сохранены.');return}
 if(['choose-test','assign-test'].includes(form.id)){const testId=form.id==='choose-test'?v('testId'):form.dataset.test,clientId=form.id==='choose-test'?form.dataset.client:v('clientId'),t=T(testId),c=C(clientId);if(!t||!c){formError(form,'Нет подходящего клиента или опросника.');return}if(ageOf(c.birth)<t.ageMin){formError(form,'Опросник недоступен для возраста клиента.');return}if(!c.consent){formError(form,'Сначала отметьте согласие на работу в карточке клиента.');return}if(event.submitter?.value==='start'){beginTest(testId,clientId);return}const already=state.assignments.some(a=>a.clientId===clientId&&a.testId===testId&&a.status==='assigned');if(already){formError(form,'Этот опросник уже назначен клиенту.');return}if(commit(s=>s.assignments.push({id:uid(),clientId,testId,status:'assigned',date:TODAY}))){closeModal();notify('Опросник назначен. Он появится в карточке клиента.')}return}
});
document.addEventListener('input',e=>{if(e.target.id==='client-search'){query=e.target.value;renderPreserving('client-search')}if(e.target.id==='test-search'){testQuery=e.target.value;renderPreserving('test-search')}});
function renderPreserving(id){const el=document.getElementById(id),pos=el?.selectionStart;render();const next=document.getElementById(id);next?.focus();if(pos!==null&&pos!==undefined)next?.setSelectionRange(pos,pos)}
document.addEventListener('change',e=>{const el=e.target;if(el.id==='client-status-filter'){clientFilter=el.value;render()}if(el.id==='client-age-filter'){clientAgeFilter=el.value;render()}if(el.id.startsWith('journal-')){journalFilter[el.id.slice(8)]=el.value;render()}if(el.id.startsWith('cert-'))updateCertificate();if(el.name==='answer'&&run){const value=+el.value;const draft={index:run.index,answers:[...run.answers]};draft.answers[run.index]=value;if(commit(s=>s.drafts[`${run.clientId}:${run.testId}`]=draft,{renderNow:false})){run.answers=draft.answers;renderRun();const sel=app.querySelector(`input[name="answer"][value="${value}"]`);sel?.focus()}}if(el.id==='import-file')importFile(el.files?.[0])});
async function importFile(file){if(!file)return;if(file.size>5e6){notify('Размер резервной копии должен быть меньше 5 МБ.');return}try{const candidate=JSON.parse(await file.text());validateState(candidate);openModal('Восстановить резервную копию?',`Клиентов: ${candidate.clients.length} · мероприятий: ${candidate.events.length}`,`<div class="notice">Текущий демосценарий будет заменён. При необходимости скачайте его перед восстановлением.</div><div class="form-footer">${btn('Отмена','close')}${btn('Скачать текущую копию','backup',{},'','download')}${btn('Восстановить','confirm-import',{},'primary')}</div>`);modal._candidate=candidate}catch(err){notify('Файл не принят: '+err.message)}}
document.addEventListener('click',e=>{const target=e.target.closest('[data-action]');if(!target||target.disabled)return;const d=target.dataset;switch(d.action){
 case 'nav':go(d.page);break;case 'open-client':clientTab='history';go('client',d.id);break;case 'open-group':go('group',d.id);break;case 'close':closeModal();break;case 'client-form':clientForm(d.id);break;case 'event-form':eventForm(d);break;case 'event-detail':eventDetail(d.id);break;case 'group-form':groupForm(d.id);break;case 'join-group':joinGroup(d.client);break;case 'client-tab':clientTab=d.tab;render();break;
 case 'clear-clients':query='';clientFilter='all';clientAgeFilter='all';render();break;case 'export-clients':exportClients();break;case 'export-events':exportEvents();break;case 'clear-journal':journalFilter={status:'all',type:'all',from:'',to:''};render();break;
 case 'metric-clients':clientFilter='active';render();break;case 'metric-events':journalFilter={status:'completed',type:'all',from:TODAY.slice(0,7)+'-01',to:TODAY};go('journal');break;case 'metric-today':dayEvents(TODAY);break;case 'metric-tests':assignmentsModal();break;
 case 'month':{const [y,m]=calendarMonth.split('-').map(Number);calendarMonth=localDate(new Date(y,m-1+Number(d.delta),1,12)).slice(0,7);render();break}case 'calendar-today':calendarMonth=TODAY.slice(0,7);render();break;case 'day-events':dayEvents(d.date);break;
 case 'test-category':testCategory=d.category;render();break;case 'clear-tests':testCategory='all';testQuery='';render();break;case 'test-detail':testDetail(d.test);break;case 'assign-test':assignTest(d.test,d.client);break;case 'choose-test':chooseTest(d.client);break;case 'assignments':assignmentsModal();break;
 case 'start-assignment':{const a=state.assignments.find(a=>a.id===d.id);if(a)beginTest(a.testId,a.clientId,a.id);break}case 'cancel-assignment':if(commit(s=>s.assignments.find(a=>a.id===d.id).status='cancelled')){closeModal();notify('Назначение отменено.')}break;
 case 'prev-question':if(run.index>0){run.index--;saveRunIndex();renderRun()}break;case 'next-question':if(run.answers[run.index]!==null){run.index++;saveRunIndex();renderRun();window.scrollTo(0,0)}break;case 'finish-test':finishTest();break;
 case 'exit-test':if(run.completed){run=null;render()}else openModal('Прервать прохождение?','Заполненные ответы останутся в браузере.',`<p class="small-note">Можно продолжить этот опросник из карточки того же клиента. Результат появится только после ответа на все вопросы.</p><div class="form-footer">${btn('Продолжить отвечать','close')}${btn('Вернуться в кабинет','confirm-exit',{},'primary')}</div>`);break;case 'confirm-exit':{const c=run.clientId;run=null;clientTab='tests';go('client',c);break}case 'run-result':{const id=run.savedResult.id,c=run.clientId;run=null;clientTab='tests';go('client',c);resultDetail(id);break}
 case 'result-detail':resultDetail(d.id);break;case 'result-client':clientTab='tests';go('client',d.client);break;case 'certificate':certificate(d.client);break;
 case 'download-certificate':{const from=document.querySelector('#cert-from').value,to=document.querySelector('#cert-to').value;if(from&&to&&from>to){notify('Проверьте период справки.');break}download('Практика-справка.html',standaloneDocument('Справка о мероприятиях',certificateHtml(C(certClient),from,to,document.querySelector('#cert-notes').checked)),'text/html;charset=utf-8');break}
 case 'print-certificate':{const from=document.querySelector('#cert-from').value,to=document.querySelector('#cert-to').value;if(from&&to&&from>to){notify('Проверьте период справки.');break}window.print();break}case 'print-result':window.print();break;
 case 'download-result':{const r=state.results.find(r=>r.id===d.id);download('Практика-разбор.html',standaloneDocument(r.title,`<h1>${esc(r.title)}</h1><p>${esc(C(r.clientId)?.name)} · ${fullDate(r.date)} · демонстрационный разбор</p>${resultBody(r)}`),'text/html;charset=utf-8');break}
 case 'cancel-event':openModal('Отменить встречу?','Запись останется в журнале со статусом «Отменено».',`<div class="form-footer">${btn('Назад','close')}${btn('Отменить встречу','confirm-cancel-event',{id:d.id},'danger')}</div>`);break;case 'confirm-cancel-event':if(commit(s=>s.events.find(x=>x.id===d.id).status='cancelled')){closeModal();notify('Встреча отменена.')}break;
 case 'restore-event':{const ev=state.events.find(x=>x.id===d.id),cf=conflictFor(state,{...ev,status:'planned'});if(cf){notify('Время уже занято другой встречей. Измените запись.');break}if(commit(s=>s.events.find(x=>x.id===d.id).status='planned')){closeModal();notify('Встреча возвращена в план.')}break}
 case 'draft-plan':{const c=C(d.client),ev=eventsFor(state,c.id).filter(e=>e.status==='completed').slice(0,3);if(!ev.length){notify('Нет проведённых встреч для черновика.');break}const text=ev.map(e=>`${fullDate(e.date)} · ${e.title}\n${e.forecast?'Дальнейшая работа: '+e.forecast:'Выводы: '+(e.conclusions||'Не внесены')}`).join('\n\n');openModal('Черновик плана из записей','Шаблонная сборка. Новые выводы не добавляются; запросов к ИИ нет.',`<div class="summary-note">${esc(text)}</div><div class="form-footer">${btn('Отмена','close')}${btn('Вставить в план','use-draft',{client:c.id},'primary')}</div>`);modal._draft=text;break}case 'use-draft':{const text=modal._draft;closeModal();const ta=document.querySelector('#plan-form textarea[name="plan"]');if(ta)ta.value=text;notify('Черновик вставлен. Проверьте текст и сохраните план.');break}
 case 'guide':guide();break;case 'about':about();break;case 'backup':download('Практика-демобаза.json',JSON.stringify(state,null,2),'application/json');break;case 'raw-backup':download('Практика-исходное-хранилище.txt',localStorage.getItem(STORAGE_KEY)||'');break;case 'import':document.querySelector('#import-file').click();break;
 case 'confirm-import':try{persist(localStorage,modal._candidate);state=modal._candidate;storageError='';recovery=false;closeModal();route={page:'clients'};render();notify('Резервная копия восстановлена.')}catch(err){notify('Не удалось сохранить копию: '+err.message)}break;
 case 'reset':openModal('Восстановить исходный сценарий?','Добавленные записи в этом браузере будут заменены.',`<div class="notice">Перед сбросом можно скачать резервную копию. Восстановятся восемь вымышленных клиентов, две группы и исходные встречи.</div><div class="form-footer">${btn('Отмена','close')}${btn('Скачать копию','backup',{},'','download')}${btn('Восстановить демоданные','confirm-reset',{},'danger')}</div>`);break;
 case 'confirm-reset':try{const seed=makeSeed();persist(localStorage,seed);state=seed;storageError='';recovery=false;run=null;route={page:'clients'};clientFilter='all';clientAgeFilter='all';query='';closeModal();render();notify('Исходный демосценарий восстановлен.')}catch(err){notify('Сброс не выполнен: '+err.message)}break;
}});
function saveRunIndex(){commit(s=>s.drafts[`${run.clientId}:${run.testId}`]={index:run.index,answers:[...run.answers]},{renderNow:false})}
function dayEvents(date){const list=state.events.filter(e=>e.date===date).sort((a,b)=>a.time.localeCompare(b.time));openModal(fullDate(date),'Расписание психолога',`${list.length?list.map(e=>`<div class="group-chip" style="margin-bottom:12px"><div><strong>${e.time} · ${esc(e.title)}</strong><p class="small-note">${esc(eventWho(e))} · ${e.duration} мин</p>${badge(STATUSES[e.status],e.status)}</div>${btn('Открыть','event-detail',{id:e.id},'sm')}</div>`).join(''):empty('Свободный день','Запланируйте встречу или групповое мероприятие.')}<div class="form-footer">${btn('Добавить встречу','event-form',{date},'primary','plus')}</div>`)}
window.addEventListener('storage',e=>{if(e.key===STORAGE_KEY){if(run){storageError='База изменилась в другой вкладке. Перед завершением опросника вернитесь в кабинет и обновите страницу.';notify(storageError);recovery=true}else{try{state=loadState(localStorage);render();notify('База обновлена из другой вкладки.')}catch{recovery=true;storageError='Изменение базы в другой вкладке не удалось прочитать.';render()}}}});
render();
